import random
import string
from typing import List

# Generator for "numeric string" inputs intended for string_to_u64
# Covers: decimal, hex (0x/0X), octal-like, binary-like, whitespace, signs,
# separators, overflow, mixed-case hex, leading zeros, empty/whitespace-only,
# and malformed tails. Max output size <= 4096 bytes.

_DEF_WHITESPACE = ["", " ", "\t", "\n", "\r", "\f", "\v", " \t\n", "\t  "]

_HEX_DIGITS_LOWER = string.digits + "abcdef"


def _rand_digits(rng: random.Random, base: int, min_len: int, max_len: int, mixed_hex: bool = True) -> str:
    if max_len < min_len:
        min_len, max_len = max_len, min_len
    n = rng.randint(min_len, max_len)
    if base == 10:
        alphabet = string.digits
        return "".join(rng.choice(alphabet) for _ in range(n))
    if base == 16:
        if mixed_hex:
            def pick():
                d = rng.choice(string.digits + "abcdef")
                if d.isalpha() and rng.random() < 0.5:
                    d = d.upper()
                return d
            return "".join(pick() for _ in range(n))
        return "".join(rng.choice(_HEX_DIGITS_LOWER) for _ in range(n))
    if base == 8:
        return "".join(rng.choice("01234567") for _ in range(n))
    if base == 2:
        return "".join(rng.choice("01") for _ in range(n))
    # Fallback
    return "".join(rng.choice(string.digits) for _ in range(n))


def _with_group_separators(rng: random.Random, s: str, sep: str) -> str:
    if not s:
        return s
    parts = []
    i = 0
    while i < len(s):
        step = rng.randint(1, 4)
        parts.append(s[i:i+step])
        i += step
    return sep.join(parts)


def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def _wrap_ws(rng: random.Random, s: str) -> str:
    left = rng.choice(_DEF_WHITESPACE)
    right = rng.choice(_DEF_WHITESPACE)
    return f"{left}{s}{right}"


def _add_sign_or_prefix(rng: random.Random, s: str, kind: str) -> str:
    out = s
    if _maybe(rng, 0.5):
        out = rng.choice(["+", "-"]) + out
    if kind == "hex":
        if _maybe(rng, 0.9):
            out = rng.choice(["0x", "0X"]) + out
    elif kind == "oct":
        if _maybe(rng, 0.7):
            out = "0" + out
        elif _maybe(rng, 0.2):
            out = rng.choice(["0o", "0O"]) + out
    elif kind == "bin":
        if _maybe(rng, 0.9):
            out = rng.choice(["0b", "0B"]) + out
    return out


def _overflow_number(rng: random.Random) -> str:
    choice = rng.randint(0, 2)
    if choice == 0:
        s = str(rng.randint(1, 9)) + _rand_digits(rng, 10, 20, 39)
        return _wrap_ws(rng, _add_sign_or_prefix(rng, s, "dec"))
    if choice == 1:
        s = _rand_digits(rng, 16, 17, 40)
        s = _add_sign_or_prefix(rng, s, "hex")
        return _wrap_ws(rng, s)
    s = _rand_digits(rng, 8, 23, 50)
    s = _add_sign_or_prefix(rng, s, "oct")
    return _wrap_ws(rng, s)


def _malformed_tail(rng: random.Random, core: str) -> str:
    tails = [
        "abc", "xyz", "_", "..", "e10", "LL", "ULL", "kb", "MiB", "g",
    ]
    return core + rng.choice(tails)


def _cases(rng: random.Random) -> List[str]:
    cases: List[str] = []

    # 0) Empty and whitespace-only
    cases.append("")
    cases.append("   \t\n")

    # 1) Small decimals including max u64
    for v in ["0", "1", "42", "18446744073709551615", "10", "999"]:
        cases.append(_wrap_ws(rng, v))

    # 2) Decimal with signs and leading zeros
    for v in ["000123", "0000", "007", "00000001"]:
        cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, v, "dec")))

    # 3) Large random decimal
    dlen = rng.randint(1, 30)
    dec = _rand_digits(rng, 10, dlen, dlen)
    if dec and dec[0] == "0":
        dec = str(rng.randint(1, 9)) + dec
    cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, dec, "dec")))

    # 4) Hex with 0x prefix
    hexlen = rng.randint(1, 24)
    hexnum = _rand_digits(rng, 16, hexlen, hexlen)
    cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, hexnum, "hex")))

    # 5) Hex without prefix
    hexlen2 = rng.randint(1, 24)
    cases.append(_wrap_ws(rng, _rand_digits(rng, 16, hexlen2, hexlen2)))

    # 6) Octal styles
    octlen = rng.randint(1, 24)
    octnum = _rand_digits(rng, 8, octlen, octlen)
    cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, octnum, "oct")))

    # 7) Binary style with 0b
    binlen = rng.randint(1, 64)
    binnum = _rand_digits(rng, 2, binlen, binlen)
    cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, binnum, "bin")))

    # 8) Grouped with separators (ensure min_len <= max_len)
    base_choice = rng.choice([10, 16])
    a = rng.randint(4, 24)
    b = rng.randint(4, 24)
    lo, hi = (a, b) if a <= b else (b, a)
    num = _rand_digits(rng, base_choice, lo, hi)
    sep = rng.choice(["_", " "])
    grouped = _with_group_separators(rng, num, sep)
    kind = "hex" if base_choice == 16 else "dec"
    cases.append(_wrap_ws(rng, _add_sign_or_prefix(rng, grouped, kind)))

    # 9) Overflow numbers
    for _ in range(3):
        cases.append(_overflow_number(rng))

    # 10) Malformed tails
    core = _add_sign_or_prefix(rng, _rand_digits(rng, 10, 1, 10), "dec")
    cases.append(_wrap_ws(rng, _malformed_tail(rng, core)))

    # 11) Hex with malformed tail
    coreh = _add_sign_or_prefix(rng, _rand_digits(rng, 16, 1, 16), "hex")
    cases.append(_wrap_ws(rng, _malformed_tail(rng, coreh)))

    # 12) Whitespace combos around simple numbers
    for l in ["\t\t", "\n ", "\r\n", "\v\f\t"]:
        for r in [" ", "\n", "\t\r"]:
            cases.append(f"{l}{rng.choice(['0', '123', '0xFF', ' 77'])}{r}")

    # 13) Scientific-notation-like (likely invalid)
    for s in ["1e9", "2E10", "-3e+5", "+4E-2"]:
        cases.append(_wrap_ws(rng, s))

    # 14) Boundary values
    cases.append("18446744073709551615")
    cases.append("18446744073709551616")
    cases.append("0xFFFFFFFFFFFFFFFF")
    cases.append("0x10000000000000000")

    # 15) Noise prefix/suffix
    noise = rng.choice(["#", ",", ";", ")", "(", "[", "]", "+", "-"])
    cases.append(f" {noise} 123")
    cases.append(f"123 {noise}")

    # Trim to 4096
    out = []
    for s in cases:
        if len(s) > 4096:
            s = s[:4096]
        out.append(s)
    return out


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    all_cases = _cases(rng)
    base = rng.choice(all_cases)
    if _maybe(rng, 0.3) and not base.endswith("\n"):
        base = base + "\n"
    s = base
    if len(s) > 4096:
        s = s[:4096]
    return s.encode("ascii", errors="ignore")

import random
import string
from typing import List

# Generator for UTF-8-like strings (possibly invalid), focusing on interesting
# code point boundaries and mixed lengths.
# We return bytes suitable for FUZZ_PARAM_STR initial corpus.
# Constraints: <= 4096 bytes, seeded randomness, no I/O.

ASCII = [bytes([c]) for c in range(0x20, 0x7f)]  # printable ASCII
CTRL = [bytes([c]) for c in range(0x00, 0x20)] + [b"\x7f"]

# Predefined valid UTF-8 sequences for various lengths
VALID_2B = [
    bytes([0xC2, 0xA2]),  # ¢
    bytes([0xC3, 0xA9]),  # é
    bytes([0xDF, 0xBF]),  # ÿ
]
VALID_3B = [
    bytes([0xE2, 0x82, 0xAC]),  # €
    bytes([0xE2, 0x98, 0x83]),  # ☃
    bytes([0xE0, 0xA4, 0xB9]),  # ह
]
VALID_4B = [
    bytes([0xF0, 0x9F, 0x98, 0x80]),  # 😀
    bytes([0xF0, 0x9F, 0x92, 0xA9]),  # 💩
    bytes([0xF0, 0x9F, 0x8E, 0x89]),  # 🎉
]

# Common invalid/edge UTF-8 patterns
INVALIDS = [
    b"\xC0\xAF",         # overlong '/'
    b"\xE0\x80\xAF",     # overlong '/'
    b"\xF0\x80\x80\xAF", # overlong '/'
    b"\xED\xA0\x80",     # lone surrogate high
    b"\xED\xBF\xBF",     # lone surrogate low
    b"\x80",              # stray continuation
    b"\xC2",              # truncated 2-byte lead
    b"\xE2\x82",         # truncated 3-byte lead
    b"\xF0\x9F\x98",     # truncated 4-byte lead
]

# Boundaries around ASCII/non-ASCII and mixed segments
WORDS = [
    b"Hello, world!",
    b"ASCII only text",
    "Caf89)s ".encode("utf-8", "ignore"),
    b"path/to/file.txt",
    b"email@example.com",
]

MIX_DELIMS = [b"\n", b"\r\n", b"\t", b" ", b"\x00"]


def rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def build_segment(r: random.Random) -> bytes:
    choice = r.randrange(0, 12)
    if choice == 0:
        return r.choice(ASCII) * r.randint(1, 8)
    if choice == 1:
        return r.choice(CTRL) * r.randint(1, 4)
    if choice == 2:
        return r.choice(VALID_2B) * r.randint(1, 4)
    if choice == 3:
        return r.choice(VALID_3B) * r.randint(1, 3)
    if choice == 4:
        return r.choice(VALID_4B) * r.randint(1, 2)
    if choice == 5:
        return r.choice(INVALIDS)
    if choice == 6:
        # Mixed ASCII word
        return r.choice(WORDS)
    if choice == 7:
        # Random printable ASCII burst
        ln = r.randint(3, 24)
        return bytes(r.choice(range(0x20, 0x7f)) for _ in range(ln))
    if choice == 8:
        # Repeating delimiter
        return r.choice(MIX_DELIMS) * r.randint(1, 8)
    if choice == 9:
        # Random valid UTF-8 code point generated procedurally
        cp_choice = r.randrange(0, 4)
        if cp_choice == 0:
            cp = r.randint(0x00, 0x7F)
        elif cp_choice == 1:
            cp = r.randint(0x80, 0x7FF)
        elif cp_choice == 2:
            # avoid surrogates
            ranges = [(0x800, 0xD7FF), (0xE000, 0xFFFF)]
            lo, hi = r.choice(ranges)
            cp = r.randint(lo, hi)
        else:
            cp = r.randint(0x10000, 0x10FFFF)
        return chr(cp).encode('utf-8')
    if choice == 10:
        # Edge of multibyte boundaries
        seqs: List[bytes] = []
        seqs += VALID_2B + VALID_3B + VALID_4B
        seqs += [b"\x7F", b"\xC2\x80", b"\xE0\xA0\x80", b"\xF0\x90\x80\x80"]
        return r.choice(seqs)
    # choice == 11
    # Random raw bytes (kept short to preserve overall validity likelihood)
    return rand_bytes(r, r.randint(1, 6))


def build_body(r: random.Random, target_size: int) -> bytes:
    chunks = []
    size = 0
    while size < target_size:
        seg = build_segment(r)
        # Occasionally insert plausible UTF-8 boundary cuts by truncating a multibyte
        if r.random() < 0.1:
            # If segment looks like multibyte, cut it
            if seg and seg[0] >= 0xC2:
                cut = r.randint(1, max(1, len(seg) - 1))
                seg = seg[:cut]
        # Control overall size
        if size + len(seg) > target_size:
            seg = seg[: max(0, target_size - size)]
        chunks.append(seg)
        size += len(seg)
        # Occasionally add delimiters/newlines
        if r.random() < 0.2 and size < target_size:
            delim = r.choice(MIX_DELIMS)
            if size + len(delim) <= target_size:
                chunks.append(delim)
                size += len(delim)
    return b"".join(chunks)


def add_scenarios(r: random.Random) -> List[bytes]:
    scenarios: List[bytes] = []
    # Empty string
    scenarios.append(b"")
    # Pure ASCII
    scenarios.append(b"The quick brown fox jumps over the lazy dog.")
    # Mixed valid multibyte and ASCII
    scenarios.append(b"Hello, \xF0\x9F\x98\x80 UTF-8! \xE2\x82\xAC")
    # Lots of newlines and tabs
    scenarios.append(b"\n\n\t\t\nEnd\n")
    # NUL in middle
    scenarios.append(b"abc\x00def\x00ghi")
    # Long run of continuation bytes
    scenarios.append(b"\x80" * 16)
    # Truncated multibyte at end
    scenarios.append(b"Prefix \xE2\x82")
    # Leading/trailing spaces
    scenarios.append(b"   lead and trail   ")
    return scenarios


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide overall size: small, medium, or larger, but <= 4096
    size_class = r.random()
    if size_class < 0.4:
        target_size = r.randint(0, 64)
    elif size_class < 0.8:
        target_size = r.randint(65, 512)
    else:
        target_size = r.randint(513, 2048)

    # Build base body
    body = build_body(r, target_size)

    # With some probability, replace with a curated scenario of interesting patterns
    scenarios = add_scenarios(r)
    if r.random() < 0.35:
        body = r.choice(scenarios)

    # Occasionally ensure the last byte is part of an incomplete sequence to test len handling
    if body and r.random() < 0.25:
        b0 = body[-1]
        if b0 < 0x80:
            # append a leading byte without continuation
            opt = r.choice([b"\xC2", b"\xE2\x82", b"\xF0\x9F\x98"])  # truncated
            if len(body) + len(opt) <= 4096:
                body += opt
        else:
            # trim to cut sequence
            body = body[:-1]

    # Ensure NUL-termination because fuzzer uses c_str()
    # We include a single NUL terminator but avoid embedding extra zeros unless already present
    if not body or body[-1] != 0:
        body += b"\x00"

    # Cap length to 4096
    return body[:4096]
